import java.util.*;class RiverBranchSpaceTest{static RiverRibbon.Point p(double x,double z){return new RiverRibbon.Point(x,z,2,100);}public static void main(String[]a){var space=new RiverBranchSpace(new RiverRibbon.Network(List.of(new RiverRibbon.Segment(p(0,0),p(100,0),2))));if(!space.crosses(p(50,-20),p(50,20)))throw new AssertionError("X crossing allowed");if(space.crosses(p(50,-20),p(50,0)))throw new AssertionError("True endpoint junction rejected");int owner=space.owner();space.add(p(50,0),p(70,20),owner,32);if(!space.crosses(p(50,20),p(70,0)))throw new AssertionError("Sibling crossing allowed");space.wetEnd(owner,16);var contact=space.contact(68,18,2,99,100,p(0,-100));if(contact==null||contact.wet())throw new AssertionError("Dry tail can be used as wet outlet");space.retire(owner);if(space.crosses(p(50,20),p(70,0)))throw new AssertionError("Discarded branch blocks valid routing");System.out.println("PASS: crossing blocked, real junction allowed, dry tails excluded as outlets, discarded paths released");}}
